body:
Wouldn't it be better to iterate over an array of pairs `{ flag, string }`? e.g.
```
struct {
	uint64_t flags;
	const char *str;
} ns[] = {
	{ CLONE_NEWCGROUP | CLONE_INTO_CGROUP, "cgroup" },
	{ CLONE_NEWIPC, "ipc" },
	{ CLONE_NEWNS, "mnt" },
	{ CLONE_NEWNET, "net" },
	{ CLONE_NEWPID, "pid" },
	{ CLONE_NEWTIME, "time" },
	{ CLONE_NEWUTS, "uts" },
	{ CLONE_NEWUSER, "user" },
};

*p = '\0';
for (size_t i = 0; i < ARRAY_SIZE(ns); ++i) {
	if (flags & ns[i].flags) {
		const char *ns_name = read_namespace_id(pid, ns[i].str);
		if (ns_name) {
			if (str != p)
				p = xappendstr(str, p, ", ");
			p = xappendstr(str, p, "%s", ns_name);
		}
	}
}
```

